<template>
  <section class="review-evidence" aria-label="复盘证据">
    <details><summary>原回答与错因</summary><div class="evidence-content"><p class="preserve">最近回答：{{ d.latest_answer || '未填写' }}</p><p>最多选3项；未选表示尚未确定。{{ d.error_cause_source === 'rule' ? '原规则建议尚未经你确认。' : '' }}</p><fieldset :disabled="!c.writable()"><legend>这次卡在哪里？</legend><div class="cause-grid"><label v-for="cause in reviewCauses" :key="cause.value"><input v-model="c.state.diagnosis.error_causes" type="checkbox" :value="cause.value" :disabled="c.state.diagnosis.error_causes.length >= 3 && !c.state.diagnosis.error_causes.includes(cause.value)" @change="clearPrimary" />{{ cause.label }}</label></div><label>主因（可不选）<select v-model="c.state.diagnosis.primary_cause"><option :value="null">不指定</option><option v-for="cause in c.state.diagnosis.error_causes" :key="cause" :value="cause">{{ reviewCauses.find(x=>x.value===cause)?.label }}</option></select></label><label>标签（最多5个，以逗号分隔）<input :value="c.state.diagnosis.custom_tags?.join('，')" maxlength="160" @input="tags" /></label><label>补充说明<textarea v-model="c.state.diagnosis.note" maxlength="300" rows="3" /></label></fieldset><div class="review-actions"><button :disabled="!c.writable()" @click="c.saveDiagnosis()">保存错因</button><button :disabled="!c.writable()" @click="clear">清除错因</button></div></div></details>
    <details @toggle="sourceToggle"><summary>资料来源</summary><div class="evidence-content"><p>资料全文，暂无原题定位。</p><p v-if="c.state.sourceLoading">正在读取原资料…</p><p v-if="c.state.sourceError" role="alert">{{ c.state.sourceError }} <button @click="c.loadSource()">重试来源</button></p><pre v-if="sourceText" class="preserve source-text">{{ sourceText }}</pre><p v-else-if="c.state.source && !c.state.sourceLoading">原资料暂未提供可读正文。</p></div></details>
    <details @toggle="historyToggle"><summary>作答与操作历史</summary><div class="evidence-content"><div class="review-actions"><button @click="c.history('attempts')">作答记录</button><button @click="c.history('events')">操作记录</button></div><p v-if="c.state.historyLoading">正在读取历史…</p><p v-if="c.state.historyError" role="alert">{{ c.state.historyError }} <button @click="c.history(c.state.historyKind,c.state.historyOffset)">重试历史</button></p><p v-else-if="!c.state.historyLoading && !c.state.historyItems.length">暂无记录。</p><ol class="history-list"><li v-for="(row, i) in c.state.historyItems" :key="i"><template v-if="'attempt_id' in row && 'is_correct' in row"><b>{{ row.is_correct === null ? '待核对' : row.answer_revealed ? '辅助练习' : row.is_correct ? '本次答对' : '本次未答对' }}</b><p class="preserve">{{ row.user_answer || '暂时不会' }}</p><p>{{ row.feedback }}</p><span>{{ reviewTime(row.created_at) }} · {{ row.rule_version || '历史规则' }}</span></template><template v-else-if="'action' in row"><b>{{ eventLabel(row.action) }}</b><p>{{ reviewTime(row.created_at) }}</p><button v-if="['pause','resume','reschedule','activate'].includes(row.action)" :disabled="!c.writable()" @click="c.previewSchedule({action:'undo',undo_event_id:row.event_id})">预览撤销此次操作</button></template></li></ol><nav class="review-pages"><button :disabled="c.state.historyLoading || c.state.historyOffset === 0" @click="c.history(c.state.historyKind,c.state.historyOffset-20)">上一组记录</button><button :disabled="c.state.historyLoading || c.state.historyOffset+20>=c.state.historyTotal" @click="c.history(c.state.historyKind,c.state.historyOffset+20)">下一组记录</button></nav></div></details>
    <details><summary>复习排期与规则</summary><div class="evidence-content"><p>当前：{{ reviewStateLabel(d) }} · 下次 {{ reviewTime(d.next_review_at) }}</p><p v-if="d.scheduler_version !== 'legacy-v1'">1／3／7／15／30天。至少3次合格验证、跨3个上海日期、首末相隔7天，才达到本轮复习标准。</p><p v-else>此题保留历史“两次答对”口径，不代表长期掌握。</p><ReviewSchedule :c="c" :d="d" /></div></details>
  </section>
</template>
<script setup lang="ts">
import { computed } from 'vue'
import type { ReviewDetail } from '../../types/wrongbook'
import type { createReviewWorkspaceController } from '../../wrongbook/workspace-state'
import { reviewCauses, reviewTime, reviewStateLabel } from '../../wrongbook/presentation'
import ReviewSchedule from './ReviewSchedule.vue'
const props = defineProps<{ c: ReturnType<typeof createReviewWorkspaceController>; d: ReviewDetail }>()
const sourceText = computed(() => { const s = props.c.state.source as { raw_text?: string } | null; return typeof s?.raw_text === 'string' ? s.raw_text : '' })
function clear() { props.c.state.diagnosis = { error_causes: [], primary_cause: null, custom_tags: [], note: '' } }
function clearPrimary() { const d = props.c.state.diagnosis; if (d.primary_cause && !d.error_causes.includes(d.primary_cause)) d.primary_cause = null }
function tags(e: Event) { props.c.state.diagnosis.custom_tags = (e.target as HTMLInputElement).value.split(/[,，]/).map(s=>s.trim()).filter(Boolean) }
function sourceToggle(e: Event) { if ((e.target as HTMLDetailsElement).open && !props.c.state.source) props.c.loadSource() }
function historyToggle(e: Event) { if ((e.target as HTMLDetailsElement).open) props.c.history('attempts') }
function eventLabel(action: string) { return ({pause:'暂停',resume:'恢复',reschedule:'改期',activate:'启用新规则',undo:'撤销',diagnosis:'错因修改',answer:'作答'} as Record<string,string>)[action] || action }
</script>
